import{_ as t,o as n,c as a,a3 as o}from"./chunks/framework.BTQ4eCVb.js";const m=JSON.parse('{"title":"Attendance — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Attendance — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/attendance"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Attendance — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/attendance"}]]},"headers":[],"relativePath":"user-guide/attendance.md","filePath":"user-guide/attendance.md","lastUpdated":1788225865000}'),s={name:"user-guide/attendance.md"};function r(i,e,l,c,d,g){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="attendance-—-user-guide" tabindex="-1">Attendance — User Guide <a class="header-anchor" href="#attendance-—-user-guide" aria-label="Permalink to &quot;Attendance — User Guide&quot;">​</a></h1><p>Enable <strong>Employees</strong> first, then install <strong>Attendance</strong> from Marketplace (free). Nav appears under <strong>HR</strong>.</p><h2 id="office-hours-self-check" tabindex="-1">Office hours &amp; self check <a class="header-anchor" href="#office-hours-self-check" aria-label="Permalink to &quot;Office hours &amp; self check&quot;">​</a></h2><p>When Attendance is installed, open <strong>Settings → Attendance</strong> to set:</p><ul><li>Office start / end time (local to <strong>Settings → General → Timezone</strong>)</li><li>Grace period (minutes) — on-site check-ins after start + grace are <strong>Late</strong></li><li>Remote office start / grace — used when staff check in as <strong>Remote</strong></li><li><strong>Show check-in / check-out</strong> — when off, self-service buttons are hidden</li><li><strong>Require late check-in reason</strong> — when late, staff must pick a reason (<strong>Other</strong> needs a written note)</li><li><strong>Auto check-in on login</strong> — off by default; when on, first login of the day can create an on-site check-in. If you are late and <strong>Require late check-in reason</strong> is on, login does <strong>not</strong> check in (use <strong>Check in</strong> and pick a reason).</li><li>Work week days (used for payroll working-day calendars)</li></ul><p>Attendance uses the same workspace <strong>Timezone</strong> as Daily Reminder Time, meetings, and task/follow-up due dates (for example <code>Asia/Karachi</code>). There is no separate attendance timezone. See <a href="/user-guide/tenant-settings#workspace-timezone">Tenant Settings — Workspace timezone</a>.</p><h2 id="self-service-check-in-check-out" tabindex="-1">Self-service check-in / check-out <a class="header-anchor" href="#self-service-check-in-check-out" aria-label="Permalink to &quot;Self-service check-in / check-out&quot;">​</a></h2><p>Linked employees with Attendance create/update permission:</p><ol><li>Open <strong>Attendance</strong> (you only see <strong>your</strong> records).</li><li>Press <strong>Check in</strong> next to search (login alone does <strong>not</strong> start the timer unless auto check-in is enabled).</li><li>Choose <strong>On-site</strong> or <strong>Remote</strong>. If you are late for that mode, pick a reason (and type a note if <strong>Other</strong>).</li><li>A live <strong>HH:MM</strong> timer starts from your saved check-in time. Closing the tab or logging out does not reset it — when you return, the timer shows the real elapsed time. The same timer (and <strong>Check in</strong> / <strong>Check out</strong>) also appears in the <strong>top header</strong> next to the light/dark theme control whenever you are linked as an employee.</li><li>Press <strong>Check out</strong> at the end of the day (optional reason; <strong>Other</strong> requires a note).</li></ol><p>Admins manage late/check-out reasons from <strong>Attendance → Reasons</strong>.</p><h2 id="managers-and-admins" tabindex="-1">Managers and admins <a class="header-anchor" href="#managers-and-admins" aria-label="Permalink to &quot;Managers and admins&quot;">​</a></h2><p>Managers and admins can:</p><ol><li>View everyone’s records, KPI stats, and who is checked in now (on-site vs remote).</li><li><strong>Record attendance</strong> for any employee and date (one record per employee per day).</li><li>Edit check-in / check-out times, status, and notes for corrections.</li><li>Manage attendance reasons (admin/owner).</li></ol><h2 id="daily-records" tabindex="-1">Daily records <a class="header-anchor" href="#daily-records" aria-label="Permalink to &quot;Daily records&quot;">​</a></h2><ol><li>Open <strong>Attendance</strong>.</li><li>Create or complete a record for the day (staff: self only; managers: any employee).</li><li>Optionally set check-in and check-out times (managers may edit either).</li><li>Choose status: Present, Absent, Half day, Remote, or Late.</li><li>Add notes if needed.</li></ol><p>Status badges use fixed colors so presence is easy to scan: <strong>Present</strong> (green), <strong>Late</strong> (red), <strong>Absent</strong> (slate), <strong>Half day</strong> (amber), <strong>Remote</strong> (blue).</p><h2 id="list-stats" tabindex="-1">List &amp; stats <a class="header-anchor" href="#list-stats" aria-label="Permalink to &quot;List &amp; stats&quot;">​</a></h2><ul><li>Filter by employee, date range, status, and search</li><li>KPI cards show totals including late; managers also see open check-ins (on-site / remote)</li><li>Soft-deleted records can be restored or permanently removed when you have permission</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Use <strong>Remote</strong> check-in for WFH days; remote late rules use the remote office start/grace settings.</li><li>Half-day is a status flag in this MVP — it does not auto-split leave balances.</li><li>Link employees to users so self check-in works.</li><li>Paid vs unpaid leave (salary deduction) is configured under Leave types — see Leave Management.</li></ul>',20)])])}const u=t(s,[["render",r]]);export{m as __pageData,u as default};
